import{_ as t,o as n,c as i,a3 as a}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"ATLAS Plugin-Vorlage","description":"Mit der offiziellen GitHub-Vorlage ein eigenes ATLAS-Plugin erstellen.","frontmatter":{"title":"ATLAS Plugin-Vorlage","description":"Mit der offiziellen GitHub-Vorlage ein eigenes ATLAS-Plugin erstellen."},"headers":[],"relativePath":"projects/atlas-plugins/plugin-template.md","filePath":"projects/atlas-plugins/plugin-template.md","lastUpdated":1792849697000}'),r={name:"projects/atlas-plugins/plugin-template.md"};function s(l,e,o,d,u,p){return n(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="atlas-plugin-vorlage" tabindex="-1">ATLAS Plugin-Vorlage <a class="header-anchor" href="#atlas-plugin-vorlage" aria-label="Permalink to &quot;ATLAS Plugin-Vorlage&quot;">​</a></h1><p>Die <a href="https://github.com/rockbaer2007/atlas-plugin-template" target="_blank" rel="noreferrer">offizielle ATLAS Plugin-Vorlage auf GitHub</a> ist ein startfertiges Repository für ein einzelnes ATLAS-Plugin. GitHub erstellt daraus mit <strong>Use this template</strong> ein eigenes Repository.</p><h2 id="plugin-generator-in-der-administration" tabindex="-1">Plugin-Generator in der Administration <a class="header-anchor" href="#plugin-generator-in-der-administration" aria-label="Permalink to &quot;Plugin-Generator in der Administration&quot;">​</a></h2><p>Die ATLAS-Administration bietet einen Plugin-Generator für ID, Name, Beschreibung, Version, Einstiegspfad und Fähigkeiten. Wähle ein MDI-Icon aus dem lokal gebündelten Katalog oder ein eigenes PNG bis 512 KiB; das Paket enthält die Grafik samt nötigen Lizenzhinweisen. Farben und Transparenz eigener PNGs bleiben erhalten. Erzeugt werden ein bearbeitbares HTML/CSS/JavaScript-Grundgerüst, Paket, <code>repository.json</code> und eine lokalisierte <code>README.md</code>, die auch einzeln heruntergeladen werden kann. Prüfe Inhalte und Pfade vor der Veröffentlichung. Der Generator erstellt kein GitHub-Repository und veröffentlicht nichts automatisch. Unterstützte manuell importierte Pakete werden nach der Kompatibilitätsprüfung auf dem App-Server installiert und unter <code>/plugin-assets/&lt;slug&gt;/</code> bereitgestellt. Die Oberfläche läuft erst beim Öffnen im Browser; Runtime-Hooks werden nicht automatisch registriert. Halte <code>entry</code> und Paketpfade konsistent.</p><p>Plugins mit eigener Sprachauswahl übernehmen die gespeicherte ATLAS-Sprachwahl beim Öffnen. Ein <code>language</code>-Parameter in der Plugin-URL hat Vorrang. Unterstützt ein Plugin die gewählte Sprache nicht, verwendet es seine konfigurierte Rückfallsprache.</p><h2 id="schnellstart" tabindex="-1">Schnellstart <a class="header-anchor" href="#schnellstart" aria-label="Permalink to &quot;Schnellstart&quot;">​</a></h2><ol><li><p>Öffne das Vorlagen-Repository und wähle <strong>Use this template</strong> → <strong>Create a new repository</strong>.</p></li><li><p>Klone das neue Repository und bearbeite <code>plugins/atlas-plugin/atlas-plugin.json</code>. Vergib eine eindeutige Plugin-ID und trage Name, Version, Beschreibung sowie nur die tatsächlich benötigten Fähigkeiten ein.</p></li><li><p>Ersetze die Beispielanwendung unter <code>plugins/atlas-plugin/</code> sowie <code>icon.svg</code>, <code>logo.svg</code> und <code>preview.svg</code> durch deine Plugin-Inhalte.</p></li><li><p>Baue und prüfe das Paket lokal:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p>Passe <code>repository.json</code> und <code>install.html</code> an dein Repository an. Der Paketgenerator übernimmt ID, Name, Version, Beschreibungen und Asset-Pfade aus dem Manifest und hält den Katalog synchron.</p></li><li><p>Der Katalog ist nach dem Push ohne GitHub Pages unter <code>https://raw.githubusercontent.com/&lt;owner&gt;/&lt;repo&gt;/main/repository.json</code> erreichbar. Aktiviere GitHub Pages zusätzlich für die öffentliche <code>install.html</code>, falls gewünscht.</p></li><li><p>Füge die Katalog-URL in der ATLAS-Administration hinzu und installiere das Plugin zum Testen.</p></li></ol><h2 id="was-enthalten-ist" tabindex="-1">Was enthalten ist <a class="header-anchor" href="#was-enthalten-ist" aria-label="Permalink to &quot;Was enthalten ist&quot;">​</a></h2><p>Die Vorlage enthält ein kleines Beispielplugin, Manifest, Repository-Katalog, Installationsseite, Paketgenerator, Validierung und einen GitHub-Actions-Workflow. Der Workflow führt Build und Prüfung bei Pushes und Pull Requests aus.</p><p>Erhöhe bei jeder Veröffentlichung die Plugin-Version und führe anschließend <code>npm run build</code> aus. Die Plugin-ID sollte nach der Veröffentlichung stabil bleiben. Prüfe vor dem Veröffentlichen insbesondere Berechtigungen und deklarierte Fähigkeiten.</p><h2 id="aktueller-installationsumfang" tabindex="-1">Aktueller Installationsumfang <a class="header-anchor" href="#aktueller-installationsumfang" aria-label="Permalink to &quot;Aktueller Installationsumfang&quot;">​</a></h2><p>Der App-Server installiert geprüfte Repository- und Importpakete im persistenten Plugin-Verzeichnis und stellt statische Webdateien unter <code>/plugin-assets/&lt;slug&gt;/</code> bereit. Beim Öffnen läuft deren JavaScript im Browser; beliebige Node-Module oder Runtime-Hooks werden nicht automatisch registriert. Die Installation ist keine Sandbox: Prüfe Paket und Browsercode vor dem Öffnen. Paketdateien enthalten Text oder ausdrücklich gekennzeichnete Base64-Assets; maximal 300 Dateien und 20 MB pro Paket. Größere Binärdateien separat bereitstellen.</p><p>Weitere Details zum Katalog und Paketformat stehen unter <a href="./repository-format">Repository-Format</a>. Die Vorlage: <a href="https://github.com/rockbaer2007/atlas-plugin-template" target="_blank" rel="noreferrer">rockbaer2007/atlas-plugin-template</a>.</p>`,13)])])}const c=t(r,[["render",s]]);export{h as __pageData,c as default};
